def time_after(hour, minute, add):
    # your code here
    return f"{hour}:{minute}"

solution.code:
def time_after(hour, minute, add):
    total = (hour * 60 + minute + add) % 1440
    return f"{total // 60:02d}:{total % 60:02d}"

def money_to_cents(text):
    dollars, _, cents = text.partition(".")
    cents = (cents + "00")[:2]
    return int(dollars) * 100 + int(cents)
